/* GpsEncBackfillMapper.updateAttdGpsEnc */
UPDATE TB_USER_ATTD_GPS
SET
      LAT_ENC = #{latEnc}
    , LON_ENC = #{lonEnc}
WHERE CMPNY_CD = #{cmpnyCd}
  AND GPS_ID   = #{rowKey}
  AND LAT_ENC IS NULL

/* GpsEncBackfillMapper.updateTbmAttendanceEnc */
UPDATE TB_TBM_ATTENDANCE
SET
      ENTRY_GPS_LAT_ENC = #{latEnc}
    , ENTRY_GPS_LON_ENC = #{lonEnc}
WHERE CMPNY_CD      = #{cmpnyCd}
  AND ATTENDANCE_CD = #{rowKey}
  AND ENTRY_GPS_LAT_ENC IS NULL

/* GpsEncBackfillMapper.updateTbmSessionEnc */
UPDATE TB_TBM_SESSION
SET
      MANAGER_GPS_LAT_ENC = #{latEnc}
    , MANAGER_GPS_LON_ENC = #{lonEnc}
WHERE CMPNY_CD   = #{cmpnyCd}
  AND SESSION_CD = #{rowKey}
  AND MANAGER_GPS_LAT_ENC IS NULL
